 {
  "document_status": "superseded",
  "title": {
    "value": "Card Dispute Intake Procedure",
    "status": "present",
    "citation": "1"
  },
  "version": {
    "value": "1.0",
    "status": "present",
    "citation": "1"
  },
  "effective_date": {
    "value": "2024-01-01",
    "status": "present",
    "citation": "1"
  },
  "purpose": {
    "value": "This procedure standardizes intake of customer card-dispute notices before an investigator reviews them.",
    "status": "present",
    "citation": "2"
  },
  "required_steps": {
    "value": "Record the merchant, amount, posting date, customer recognition statement, and available receipt. Create a review item and route it to Card Disputes. Do not promise reimbursement.",
    "status": "present",
    "citation": "3"
  },
  "exceptions": {
    "value": "If the customer also reports unrecognized transactions, pause ordinary intake and escalate for possible fraud review.",
    "status": "present",
    "citation": "4"
  }
}

 {
  "document_status": "valid",
  "title": {
    "value": "Card Dispute Intake Procedure",
    "status": "present",
    "citation": "1"
  },
  "version": {
    "value": "2.0",
    "status": "present",
    "citation": "1"
  },
  "effective_date": {
    "value": "2025-01-01",
    "status": "present",
    "citation": "1"
  },
  "purpose": {
    "value": "This procedure governs initial handling of customer card-dispute notices and preserves the human decision boundary.",
    "status": "present",
    "citation": "2"
  },
  "required_steps": {
    "value": ["Capture merchant, amount, posting date, whether the merchant is recognized, and supporting-document availability.", "Create a review item, redact identifiers from free-text notes, and route to Card Disputes.", "A human investigator decides any outcome."],
    "status": "present",
    "citation": "3"
  },
  "exceptions": {
    "value": ["Messages containing both recognized and unrecognized transactions must be escalated rather than automatically routed."],
    "status": "present",
    "citation": "4"
  }
}

 {
  "document_status": "valid",
  "title": {
    "value": "Lost Card Response Procedure",
    "status": "present",
    "citation": "1"
  },
  "version": {
    "value": "3.1",
    "status": "present",
    "citation": "1"
  },
  "effective_date": {
    "value": "2025-03-15",
    "status": "present",
    "citation": "1"
  },
  "purpose": {
    "value": "The procedure explains how staff record a reported lost physical card.",
    "status": "present",
    "citation": "2"
  },
  "required_steps": {
    "value": "Confirm the customer through approved authentication, mark the card for specialist review, record the last known possession date, and offer transfer to the replacement-card team.",
    "status": "present",
    "citation": "3"
  },
  "exceptions": {
    "value": "If unauthorized transactions are also reported, open a fraud-review item and do not state that the customer will be reimbursed.",
    "status": "present",
    "citation": "4"
  }
}

