 {
  "document_status": "valid",
  "title": {
    "value": "Complaint Acknowledgement Procedure",
    "status": "present",
    "citation": "1"
  },
  "version": {
    "value": "2.2",
    "status": "present",
    "citation": "1"
  },
  "effective_date": {
    "value": "2025-05-01",
    "status": "present",
    "citation": "1"
  },
  "purpose": {
    "value": "This procedure standardizes neutral acknowledgement of formal service complaints.",
    "status": "present",
    "citation": "2"
  },
  "required_steps": {
    "value": "Record the complaint category, acknowledge receipt, and send the item to a human complaint owner. Do not promise a resolution date that has not been approved.",
    "status": "present",
    "citation": "3"
  },
  "exceptions": {
    "value": "Threats of immediate physical harm follow the emergency escalation procedure.",
    "status": "present",
    "citation": "5"
  }
}

 {
  "document_status": "valid",
  "title": {
    "value": "Address Change Verification Procedure",
    "status": "present",
    "citation": "1"
  },
  "version": {
    "value": "4.0",
    "status": "present",
    "citation": "1"
  },
  "effective_date": {
    "value": "2025-01-20",
    "status": "present",
    "citation": "1"
  },
  "purpose": {
    "value": "This procedure covers customer-requested mailing-address changes.",
    "status": "present",
    "citation": "2"
  },
  "required_steps": {
    "value": ["Authenticate the customer, capture the new address, repeat it for confirmation, and create an auditable change record."],
    "status": "present",
    "citation": "3"
  },
  "exceptions": {
    "value": ["A request paired with suspicious account-access activity must be escalated before the address is changed."],
    "status": "present",
    "citation": "4"
  }
}

 {
  "document_status": "valid",
  "title": {
    "value": "Lending Inquiry Referral Procedure",
    "status": "present",
    "citation": "1"
  },
  "version": {
    "value": "1.3",
    "status": "present",
    "citation": "1"
  },
  "effective_date": {
    "value": "2024-11-10",
    "status": "present",
    "citation": "1"
  },
  "purpose": {
    "value": "This procedure routes general lending inquiries without making credit decisions.",
    "status": "present",
    "citation": "2"
  },
  "required_steps": {
    "value": "Record the product of interest and preferred contact channel, then refer the inquiry to a licensed lending specialist. Staff must not quote an approval probability.",
    "status": "present",
    "citation": "3"
  },
  "exceptions": {
    "value": "Existing-loan servicing disputes follow the loan-servicing procedure rather than this referral procedure.",
    "status": "present",
    "citation": "4"
  }
}

